"""Procedural Lavax rig parts + rig.json (magma ape: hunched charred-basalt body, glowing lava cracks, long knuckle-dragging arms, blue eyes). Original art generated by this
script (no legacy pixels used). Run: python3 tools/assets/rig-gen/lavax.py <out_rig_dir>  (needs Pillow + numpy)
Look matches the Fiara/Pax/Treenoc/Morblass/Rokcore rigs: cel-banded ramp, dark outline, light upper-left rim.
"""
import json, os, sys, zlib
import numpy as np
from PIL import Image, ImageDraw, ImageFilter
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import palette

OUT = sys.argv[1]
os.makedirs(os.path.join(OUT, "parts"), exist_ok=True)
SS = 4
W = 80 * SS
FIRE = palette.ELEMENT_RAMPS["fire"]
# charred basalt shading toward ember brown; lava glows in the cracks
STONE = [(0.0, (24, 14, 14)), (0.3, (66, 32, 26)), (0.58, (96, 40, 28)), (0.82, (140, 66, 36)), (1.0, (190, 104, 56))]
LAVA = [(0.0, FIRE[2]), (0.5, FIRE[3]), (1.0, FIRE[4])]
OUTLINE = np.array(palette.outline("fire"), np.float32)
RIM = np.array((255, 196, 130), np.float32)
FACE = (14, 8, 8)
EYE = (150, 210, 255)

# geometry in the 80x80 rest frame, E view (y down)
G = {
 "tail": dict(pts=[(20,54),(48,54),(55,68),(52,78),(37,78),(34,70),(30,78),(15,78),(18,66)], joint=(34,58), z=1, parent=None, bias=-0.1),  # legs
 "armB": dict(pts=[(42,30),(52,30),(60,42),(64,58),(70,70),(62,75),(54,68),(48,52)], joint=(47,33), z=2, parent="torso", bias=-0.18),
 "torso": dict(pts=[(15,54),(10,38),(17,24),(33,20),(48,25),(55,38),(53,54),(40,59)], joint=(35,46), z=5, parent="tail", bias=0.0),
 "head": dict(pts=[(40,24),(43,15),(51,12),(58,16),(60,25),(54,31),(45,30)], joint=(48,29), z=7, parent="torso", bias=0.05),
 "armF": dict(pts=[(13,30),(26,28),(33,42),(31,58),(36,71),(26,77),(16,70),(14,52),(9,40)], joint=(24,32), z=8, parent="torso", bias=0.1),
}

def view_tf(view, part):
    if view == "E":
        return dict(sx=1.0, dx=-3 if part == "head" else 0, dy=0)
    if view == "SE":
        d = dict(sx=0.93, dx=2, dy=1)
        if part == "head": d = dict(sx=1.06, dx=-8, dy=4, scale=1.06)
        if part == "armF": d = dict(sx=0.95, dx=-3, dy=1)
        if part == "armB": d = dict(sx=0.95, dx=3, dy=1)
        if part == "torso": d = dict(sx=0.96, dx=1, dy=2)
        return d
    d = dict(sx=0.93, dx=-1, dy=-1)  # NE: seen from behind
    if part == "head": d = dict(sx=0.92, dx=-6, dy=-2, scale=0.94)
    if part == "armF": d = dict(sx=0.95, dx=1, dy=-1)
    if part == "armB": d = dict(sx=0.95, dx=2, dy=-1)
    if part == "torso": d = dict(sx=1.0, dx=-2, dy=-1)
    return d

def apply(tf, p, c=(40, 40)):
    s = tf.get("scale", 1.0)
    return (c[0] + (p[0] - c[0]) * tf["sx"] * s + tf["dx"], c[1] + (p[1] - c[1]) * s + tf["dy"])

def noise(rs, scale, sx=1, sy=1):
    """Smooth noise, stretched sx/sy times (flow streaks)."""
    h = max(2, W // (scale * sy) + 2); w = max(2, W // (scale * sx) + 2)
    small = rs.rand(h, w)
    return np.asarray(Image.fromarray((small * 255).astype(np.uint8)).resize((W, W), Image.BICUBIC), np.float32) / 255.0

def render(name, view, pts, g, seed):
    m = Image.new("L", (W, W), 0)
    d = ImageDraw.Draw(m)
    d.polygon([(x * SS, y * SS) for x, y in pts], fill=255)
    m = m.filter(ImageFilter.GaussianBlur(SS * 0.35))
    ma = np.asarray(m, np.float32) / 255.0
    rs = np.random.RandomState(seed)
    coarse = noise(rs, 8); mid = noise(rs, 4); fine = noise(rs, 2)
    yy, xx = np.mgrid[0:W, 0:W].astype(np.float32) / W
    # blocky plates: quantised coarse noise gives flat facets, lit from the upper left
    plate = np.round(coarse * 4.0) / 4.0
    t = 0.7 - 0.4 * yy - 0.25 * xx + 0.45 * (plate - 0.5) + 0.15 * (mid - 0.5) + 0.08 * (fine - 0.5) + g["bias"] + 0.2
    crack = np.abs(mid - 0.5) < 0.05  # lava seams where a noise field crosses 0.5
    t = np.clip(np.round(np.clip(t, 0, 1) * 5.0) / 5.0, 0, 1)
    rgb = palette.ramp(STONE, t)
    lt = np.clip(np.round(np.clip(0.2 + 0.9 * (1.0 - np.abs(mid - 0.5) / 0.05) * (0.5 + 0.5 * fine), 0, 1) * 3.0) / 3.0, 0, 1)
    rgb = np.where(crack[..., None], palette.ramp(LAVA, lt), rgb)
    inner = np.asarray(m.filter(ImageFilter.MinFilter(SS * 3 + 1)), np.float32) / 255.0
    edge = np.clip(np.subtract(ma, inner), 0, 1)
    shifted = np.roll(np.roll(ma, SS * 2, axis=0), SS * 2, axis=1)
    lit = np.clip(np.subtract(ma, shifted), 0, 1) * inner.clip(0, 1)
    lit = np.asarray(Image.fromarray((lit * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(SS * 0.5)), np.float32) / 255.0
    rgb = rgb * (1 - 1.0 * edge[..., None]) + OUTLINE[None, None, :] * (1.0 * edge[..., None])
    rgb = rgb * (1 - 0.7 * lit[..., None]) + RIM[None, None, :] * (0.7 * lit[..., None])
    return Image.fromarray(np.dstack([np.clip(rgb, 0, 255), ma * 255.0]).astype(np.uint8), "RGBA")

def face(im, tf, view):
    d = ImageDraw.Draw(im)
    x0, y0 = apply(tf, (48, 17)); x1, y1 = apply(tf, (58, 25))
    d.rectangle([x0 * SS, y0 * SS, x1 * SS, y1 * SS], fill=FACE + (255,))  # recessed brow slot
    for ex, ey in ((51, 21), (55, 21)):
        x, y = apply(tf, (ex, ey))
        d.ellipse([x * SS - 1.6 * SS, y * SS - 1.2 * SS, x * SS + 1.6 * SS, y * SS + 1.2 * SS], fill=EYE + (255,))

parts = []
for view in ("E", "SE", "NE"):
    tfs = {k: view_tf(view, k) for k in G}
    for k, g in G.items():
        pts = [apply(tfs[k], p) for p in g["pts"]]
        im = render(k, view, pts, g, zlib.crc32((k + view).encode()) % 9973 + 7)
        if k == "head" and view != "NE":
            face(im, tfs[k], view)
        small = im.resize((80, 80), Image.LANCZOS)
        a = np.asarray(small)
        ys, xs = np.nonzero(a[..., 3] > 8)
        x0, x1, y0, y1 = int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1
        crop = small.crop((x0, y0, x1, y1))
        fname = f"{k}.png" if view == "E" else f"{k}_{view.lower()}.png"
        crop.save(os.path.join(OUT, "parts", fname))
        parts.append(dict(view=view, id=k, png=fname, joint=apply(tfs[k], g["joint"]), off=(x0, y0), size=crop.size))

byv = {v: {e["id"]: e for e in parts if e["view"] == v} for v in ("E", "SE", "NE")}
def pv(e):
    return [int(round(e["joint"][0])) - e["off"][0], int(round(e["joint"][1])) - e["off"][1]]
def at(v, pid):
    g = G[pid]; e = byv[v][pid]
    jx, jy = int(round(e["joint"][0])), int(round(e["joint"][1]))
    if g["parent"] is None:
        return [jx, jy]
    pe = byv[v][g["parent"]]
    return [jx - int(round(pe["joint"][0])), jy - int(round(pe["joint"][1]))]

rig_parts = []
for pid in list(G):
    g = G[pid]
    p = {"id": pid}
    if g["parent"]: p["parent"] = g["parent"]
    p["png"] = byv["E"][pid]["png"]; p["pivot"] = pv(byv["E"][pid]); p["at"] = at("E", pid); p["z"] = g["z"]
    p["views"] = {v: {"png": byv[v][pid]["png"], "pivot": pv(byv[v][pid]), "at": at(v, pid)} for v in ("SE", "NE")}
    rig_parts.append(p)

def c(**kw): return kw
def c(**kw): return kw
actions = {
 "idle": dict(frames=4, curves={  # heavy breathing
    "torso": c(dy=[0, -1, -1, 0]),
    "head": c(rot=[0, -1, -2, -1], dy=[0, 0, 1, 0]),
    "armF": c(rot=[0, 2, 3, 1]),
    "armB": c(rot=[0, -2, -3, -1]),
 }),
 "walk": dict(frames=4, curves={  # lumbering: body bobs, arms swing against each other
    "tail": c(dy=[0, -1, 0, -1], rot=[-2, 0, 2, 0]),
    "torso": c(rot=[3, 1, 3, 1], dy=[1, 0, 1, 0]),
    "head": c(rot=[-3, -1, -3, -1]),
    "armF": c(rot=[14, 0, -16, 0]),
    "armB": c(rot=[-16, 0, 14, 0]),
 }),
 # fire buff: both fists raise, the body rears back, then slam down
 "cast": dict(frames=4, curves={
    "tail": c(dy=[0, 0, 0, 1]),
    "torso": c(rot=[0, -4, -5, 4], dy=[0, -1, -2, 2]),
    "head": c(rot=[0, -5, -6, 3]),
    "armF": c(rot=[-8, -50, -76, 10]),
    "armB": c(rot=[-6, -44, -66, 8]),
 }),
}

json.dump(dict(dirs=["E", "SE", "NE"], parts=rig_parts, actions=actions), open(os.path.join(OUT, "rig.json"), "w"), indent=2)
open(os.path.join(OUT, "license.txt"), "w").write(
"""Rig parts for lavax: original art generated by tools/assets/rig-gen/lavax.py (WP-art-consistency-batches, 2026-11-12, Claude). No pixels
are copied; silhouette and colours chosen by eye after the legacy public/assets/img/map/lavax.png. Licence: same as the
repository's own original code and art (still to be decided in README.md; owner to confirm).
""")
print("ok")
